CREATE TABLE family_birthday (person_id TEXT PRIMARY KEY REFERENCES person(person_id),birth_date TEXT NOT NULL,source_status TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE family_birthday_source (person_id TEXT NOT NULL REFERENCES family_birthday(person_id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,source_ref TEXT NOT NULL,PRIMARY KEY(person_id,ordinal),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE family_birth_cohort (cohort_id INTEGER PRIMARY KEY,start_year INTEGER NOT NULL,end_year INTEGER NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE family_birth_cohort_assignment (person_id TEXT PRIMARY KEY REFERENCES person(person_id),cohort_id INTEGER NOT NULL REFERENCES family_birth_cohort(cohort_id),baseline_birth_date TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE family_tree (tree_id TEXT PRIMARY KEY,collapse_year INTEGER NOT NULL,reference_date TEXT NOT NULL,status TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE family_tree_source (tree_id TEXT NOT NULL REFERENCES family_tree(tree_id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,source_path TEXT NOT NULL,PRIMARY KEY(tree_id,ordinal),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE family_node (node_id TEXT PRIMARY KEY,person_id TEXT UNIQUE REFERENCES person(person_id),node_kind TEXT NOT NULL,name TEXT NOT NULL,name_en TEXT,birth_date TEXT,death_date TEXT,status TEXT NOT NULL,lineage_surname TEXT,lineage_bongwan TEXT,lineage_clan TEXT,generation_exception_reason TEXT,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE family_node_source (node_id TEXT NOT NULL REFERENCES family_node(node_id),source_kind TEXT NOT NULL,ordinal INTEGER NOT NULL CHECK(ordinal>=0),source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,source_path TEXT NOT NULL,source_anchor TEXT,PRIMARY KEY(node_id,source_kind,ordinal),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE family_node_timeline (node_id TEXT NOT NULL REFERENCES family_node(node_id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),year INTEGER NOT NULL,summary TEXT NOT NULL,summary_en TEXT,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,PRIMARY KEY(node_id,ordinal),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE family_edge (edge_id TEXT PRIMARY KEY,from_node_id TEXT NOT NULL REFERENCES family_node(node_id),to_node_id TEXT NOT NULL REFERENCES family_node(node_id),edge_type TEXT NOT NULL,parent_role TEXT,status TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE family_edge_source (edge_id TEXT NOT NULL REFERENCES family_edge(edge_id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,source_path TEXT NOT NULL,source_anchor TEXT,PRIMARY KEY(edge_id,ordinal),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE family_parent_status (person_id TEXT PRIMARY KEY REFERENCES person(person_id),status TEXT NOT NULL,known_parent_id TEXT REFERENCES family_node(node_id),known_relationship TEXT,source_ref_path TEXT NOT NULL,source_ref_anchor TEXT,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE family_role_decision (decision_group TEXT NOT NULL,ordinal INTEGER NOT NULL CHECK(ordinal>=0),edge_id TEXT REFERENCES family_edge(edge_id),from_node_id TEXT REFERENCES family_node(node_id),to_node_id TEXT REFERENCES family_node(node_id),parent_role TEXT,decision_kind TEXT,category TEXT,source_status TEXT,basis TEXT,selection_ref TEXT,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,PRIMARY KEY(decision_group,ordinal),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE household_manifest (manifest_id TEXT PRIMARY KEY,status TEXT NOT NULL,scope_kind TEXT NOT NULL,isolated_at_audit INTEGER NOT NULL,all_isolated_authored INTEGER NOT NULL CHECK(all_isolated_authored IN (0,1)),quantity_mode TEXT NOT NULL,court_count INTEGER NOT NULL,direct_retainer_count INTEGER NOT NULL,quantity_source TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE household_person (person_id TEXT PRIMARY KEY REFERENCES person(person_id),name TEXT NOT NULL,person_faith_status TEXT NOT NULL,house_faith_status TEXT NOT NULL,humanoid_admission TEXT NOT NULL,gender_preference TEXT NOT NULL,political_position TEXT NOT NULL,normalized_social_contact INTEGER NOT NULL CHECK(normalized_social_contact IN (0,1)),family_parent INTEGER NOT NULL CHECK(family_parent IN (0,1)),faith_unresolved INTEGER NOT NULL CHECK(faith_unresolved IN (0,1)),private_retainer_status TEXT,background_contact_authoring TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE family_source_metadata (source_id INTEGER NOT NULL REFERENCES source_file(source_id),field_name TEXT NOT NULL,value_kind TEXT NOT NULL CHECK(value_kind IN ('null','string','number','boolean')),text_value TEXT,integer_value INTEGER,boolean_value INTEGER CHECK(boolean_value IN (0,1)),json_pointer TEXT NOT NULL,PRIMARY KEY(source_id,field_name),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE family_role_decision_fact (decision_group TEXT NOT NULL,ordinal INTEGER NOT NULL,field_path TEXT NOT NULL,value_kind TEXT NOT NULL CHECK(value_kind IN ('null','string','number','boolean')),text_value TEXT,integer_value INTEGER,boolean_value INTEGER CHECK(boolean_value IN (0,1)),source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,PRIMARY KEY(decision_group,ordinal,field_path),FOREIGN KEY(decision_group,ordinal) REFERENCES family_role_decision(decision_group,ordinal),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE family_role_decision_source (decision_group TEXT NOT NULL,ordinal INTEGER NOT NULL,ref_ordinal INTEGER NOT NULL CHECK(ref_ordinal>=0),source_path TEXT NOT NULL,source_anchor TEXT,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,PRIMARY KEY(decision_group,ordinal,ref_ordinal),FOREIGN KEY(decision_group,ordinal) REFERENCES family_role_decision(decision_group,ordinal),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE household_court_retainer_source (court_id TEXT NOT NULL,person_id TEXT NOT NULL,source_row INTEGER NOT NULL,retainer_json_pointer TEXT NOT NULL,ordinal INTEGER NOT NULL CHECK(ordinal>=0),source_path TEXT NOT NULL,source_anchor TEXT,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,PRIMARY KEY(court_id,person_id,source_row,retainer_json_pointer,ordinal),FOREIGN KEY(court_id,person_id,source_row,retainer_json_pointer) REFERENCES household_court_retainer(court_id,person_id,source_row,json_pointer),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE household_humanoid_context_source (actor_id TEXT NOT NULL REFERENCES household_humanoid_context(actor_id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),source_path TEXT NOT NULL,source_anchor TEXT,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,PRIMARY KEY(actor_id,ordinal),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE household_policy_political_position (entity_key TEXT PRIMARY KEY,position TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE household_policy_source (ordinal INTEGER PRIMARY KEY CHECK(ordinal>=0),source_path TEXT NOT NULL,source_anchor TEXT,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE household_person_source (person_id TEXT NOT NULL REFERENCES household_person(person_id),source_kind TEXT NOT NULL,ordinal INTEGER NOT NULL CHECK(ordinal>=0),source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,source_path TEXT NOT NULL,source_anchor TEXT,PRIMARY KEY(person_id,source_kind,ordinal),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE household_link (link_id TEXT PRIMARY KEY,owner_person_id TEXT NOT NULL REFERENCES household_person(person_id),recipient_person_id TEXT REFERENCES person(person_id),recipient_node_id TEXT REFERENCES family_node(node_id),recipient_key TEXT NOT NULL,recipient_kind TEXT NOT NULL,link_type TEXT NOT NULL,direction TEXT,role TEXT NOT NULL,status TEXT NOT NULL,basis TEXT,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,CHECK((recipient_person_id IS NOT NULL)+(recipient_node_id IS NOT NULL)=1),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE household_link_source (link_id TEXT NOT NULL REFERENCES household_link(link_id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,source_path TEXT NOT NULL,source_anchor TEXT,PRIMARY KEY(link_id,ordinal),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE household_court (court_id TEXT PRIMARY KEY,owner_person_id TEXT NOT NULL REFERENCES household_person(person_id),state_id TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE household_court_retainer (court_id TEXT NOT NULL REFERENCES household_court(court_id),person_id TEXT NOT NULL REFERENCES person(person_id),liege_person_id TEXT NOT NULL REFERENCES person(person_id),source_row INTEGER NOT NULL,role TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,PRIMARY KEY(court_id,person_id,source_row,json_pointer),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE household_humanoid_context (actor_id TEXT PRIMARY KEY,custodian_person_id TEXT NOT NULL REFERENCES person(person_id),steward_house_id TEXT NOT NULL,scope TEXT NOT NULL,assignment_action TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE diaspora_lineage (lineage_key TEXT PRIMARY KEY,current_person_id TEXT NOT NULL REFERENCES person(person_id),source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE diaspora_member (member_key TEXT PRIMARY KEY,lineage_key TEXT NOT NULL REFERENCES diaspora_lineage(lineage_key),person_id TEXT UNIQUE REFERENCES person(person_id),generation INTEGER NOT NULL,name_ko TEXT NOT NULL,name_en TEXT NOT NULL,birth_date TEXT NOT NULL,timeline_ko TEXT NOT NULL,timeline_en TEXT NOT NULL,narrative_ko TEXT NOT NULL,narrative_en TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE diaspora_member_parent (member_key TEXT NOT NULL REFERENCES diaspora_member(member_key),parent_member_key TEXT REFERENCES diaspora_member(member_key),parent_node_id TEXT REFERENCES family_node(node_id),parent_key TEXT NOT NULL,parent_role TEXT,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,PRIMARY KEY(member_key,parent_key),CHECK((parent_member_key IS NOT NULL)+(parent_node_id IS NOT NULL)=1),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE diaspora_member_event (member_key TEXT NOT NULL REFERENCES diaspora_member(member_key),ordinal INTEGER NOT NULL CHECK(ordinal>=0),event_year INTEGER NOT NULL,event_kind TEXT NOT NULL,event_date TEXT,source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,PRIMARY KEY(member_key,ordinal),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
CREATE TABLE household_policy_value (policy_key TEXT NOT NULL,ordinal INTEGER NOT NULL CHECK(ordinal>=0),value_kind TEXT NOT NULL CHECK(value_kind IN ('null','string','number','boolean')),text_value TEXT,integer_value INTEGER,boolean_value INTEGER CHECK(boolean_value IN (0,1)),source_id INTEGER NOT NULL REFERENCES source_file(source_id),json_pointer TEXT NOT NULL,PRIMARY KEY(policy_key,ordinal),CHECK((value_kind='null' AND text_value IS NULL AND integer_value IS NULL AND boolean_value IS NULL) OR (value_kind='string' AND text_value IS NOT NULL AND integer_value IS NULL AND boolean_value IS NULL) OR (value_kind='number' AND text_value IS NULL AND integer_value IS NOT NULL AND boolean_value IS NULL) OR (value_kind='boolean' AND text_value IS NULL AND integer_value IS NULL AND boolean_value IS NOT NULL)),FOREIGN KEY(source_id,json_pointer) REFERENCES source_record(source_id,json_pointer)) STRICT;
